1064: (function() {
1065:     var btn = document.getElementById('help-menu-btn');
1066:     var panel = document.getElementById('help-menu-panel');
1067:     if (!btn || !panel) return;
1068:     function close() {
1069:         panel.hidden = true;
1070:         btn.setAttribute('aria-expanded', 'false');
1071:     }
1072:     btn.addEventListener('click', function(e) {
1073:         e.stopPropagation();
1074:         var opening = panel.hidden;
1075:         panel.hidden = !opening;
1076:         btn.setAttribute('aria-expanded', String(opening));
1077:     });
1078:     document.addEventListener('click', function(e) {
1079:         if (!panel.hidden && !panel.contains(e.target) && !btn.contains(e.target)) close();
1080:     });
1081:     document.addEventListener('keydown', function(e) {
1082:         if (e.key === 'Escape' && !panel.hidden) close();
1083:     });
1084: })();
1085: </script>
